package jsonconfig

import "encoding/json"

type Config struct {
	// BUG: wrong json tag — should be "host" not "hostname"
	Host    string `json:"hostname"`
	Port    int    `json:"port"`
	Debug   bool   `json:"debug"`
}

// BUG: ignores unmarshal error, always returns empty config
func ParseConfig(data []byte) (Config, error) {
	var c Config
	json.Unmarshal(data, &c)
	return c, nil
}

// BUG: returns 0 instead of defaultPort when port is 0
func EffectivePort(c Config, defaultPort int) int {
	if c.Port == 0 {
		return 0
	}
	return c.Port
}

package jsonconfig

import "testing"

func TestParseHost(t *testing.T) {
	data := []byte(`{"host": "example.com", "port": 9000}`)
	c, err := ParseConfig(data)
	if err != nil {
		t.Fatal(err)
	}
	if c.Host != "example.com" {
		t.Fatalf("want example.com, got %q", c.Host)
	}
}

func TestParseInvalidJSON(t *testing.T) {
	_, err := ParseConfig([]byte(`{bad json}`))
	if err == nil {
		t.Fatal("expected error for invalid JSON")
	}
}

func TestEffectivePortDefault(t *testing.T) {
	c := Config{Port: 0}
	if got := EffectivePort(c, 8080); got != 8080 {
		t.Fatalf("want 8080, got %d", got)
	}
}

func TestEffectivePortExplicit(t *testing.T) {
	c := Config{Port: 9000}
	if got := EffectivePort(c, 8080); got != 9000 {
		t.Fatalf("want 9000, got %d", got)
	}
}

func TestParseDebugFlag(t *testing.T) {
	data := []byte(`{"host": "localhost", "port": 80, "debug": true}`)
	c, _ := ParseConfig(data)
	if !c.Debug {
		t.Fatal("want debug=true")
	}
}
